/*
 * JOCKY Stealth Runtime — Build Smoke Test
 * Compiled alongside jocky_runtime_linux_stealth.c to verify the
 * direct-syscall layer is functional before deployment.
 *
 * This file is the polymorphic build entry point: poly_engine.py copies it
 * into the build directory together with jocky_runtime_linux_stealth.c and
 * compiles both with randomised flags to produce a unique binary per build.
 */

#include <stddef.h>
#include "jocky_build_identity.h"   /* generated by poly_engine per build */

/* Forward declarations from jocky_runtime_linux_stealth.c */
extern void jocky_stealth_init(void);
extern long jocky_syscall_open(const char *path, int flags, int mode);
extern long jocky_syscall_close(int fd);
extern long jocky_syscall_write(int fd, const void *buf, size_t count);

static void write_str(int fd, const char *s) {
    size_t len = 0;
    while (s[len]) len++;
    jocky_syscall_write(fd, s, len);
}

int main(void) {
    jocky_stealth_init();
    write_str(1, "[JOCKY] stealth smoke-test build_id=");
    write_str(1, JOCKY_BUILD_ID_STR);
    write_str(1, "\n");

    /* Verify we can open /proc/self/status via direct syscall */
    long fd = jocky_syscall_open("/proc/self/status", 0 /* O_RDONLY */, 0);
    if (fd < 0) {
        write_str(2, "[JOCKY] FAIL: could not open /proc/self/status\n");
        return 1;
    }
    jocky_syscall_close((int)fd);
    write_str(1, "[JOCKY] OK: direct syscall layer functional\n");
    return 0;
}
